    ],
    'now-is-the-month-of-maying' => [
        'soprano' => 'Carries Morley\'s dancing tune, often up on its top D, on "playing", "his bonny lass" and the fa las, and down to the D an octave below in the fa las.',
        'alto' => 'Sings a tune of its own close under the soprano, mostly on G and F#, reaching A only in the second half, on "his bonny", "grass" and its fa las.',
        'tenor' => 'Sings Morley\'s two tenor parts joined into one, mostly on D, up to F on "his" and down to E in the second half\'s fa las.',
        'bass' => 'Sings the foundation, mostly D and G, from a low G on "Now", "Maying", "When" and the fa las up to A on "bonny" and the "Fa" after "grass".',
    ],
    'asleep-in-the-deep' => [
        'soprano' => 'Holds soft chords on "oo" high above the bass\'s tune, mostly on C, with B-flat, D and A.',
        'alto' => 'Holds soft chords on "oo" in the middle, mostly on A and E, between a low A and a C.',
        'tenor' => 'Holds soft chords on "oo" close to the bass\'s tune, mostly on C, rising to F as the refrain begins.',
        'bass' => 'Carries Petrie\'s tune and all the words, from "Stormy the night" up to a high D on "lovers stand", the first "Sailor" and "Danger", and down to the low F of the last "Beware!".',
    ],
    'with-cat-like-tread' => [
        'soprano' => 'Carries the pirates\' tune, from "Come, friends, who plough the sea" to the loud "With cat-like tread", reaching its top E on "burglaree", "way" and the "we" of "we feel".',
        'alto' => 'Sings the pirates\' words under the tune, from a low G# on "Truce", "navigation", "Take" and "station" up to A on "Upon", "prey", "steal" and "cautious".',
        'tenor' => 'Is a policeman: sings "Tarantara" and its "ra"s under the pirates, mostly on E and F#, up to A near the end.',
        'bass' => 'Is a policeman too: sings "Tarantara" on Sullivan\'s bass line, mostly E, A and D, with B, under the pirates\' march.',
    ],
    'abide-with-me' => [
        'soprano' => 'Carries Monk\'s calm tune, from E-flat up to C on "falls" and "deepens", and back down to E-flat on the last "me".',
        'alto' => 'Sings the words close under the tune on just four notes, mostly E-flat and D, stepping through E natural to F under "comforts flee".',
        'tenor' => 'Sings the words in the middle of the chords, mostly on B-flat, from a low E-flat on "fast falls" and the "abide" of "Lord, with me abide" up to C on "Lord", "fail, and comforts" and the last "abide".',
        'bass' => 'Sings the bass line, mostly roots, on E-flat, B-flat and C above all, down to a low G on "fast" and "helpers", and up to A-flat on "Help".',
    ],
    'shall-we-gather' => [
        'soprano' => 'Carries Lowry\'s tune, cheerful and steady, up to its top E-flat on "gather at" and "saints at", and down to the low E-flat on each "God".',
        'alto' => 'Sings mostly in thirds under the tune, on E-flat, F, G and D, high with it on "Yes, we\'ll gather" and "Gather with the saints", and ends on a low G under the last "God".',
        'tenor' => 'Sings the words mostly on B-flat, rising to E-flat on "river", "forever" and "Gather with the", and sings "Yes, we\'ll gather" on C, a sixth under the alto.',
        'bass' => 'Sings the roots on just three notes, E-flat, B-flat and A-flat, high on A-flat for the chorus\'s "Yes, we\'ll gather" and "Gather with the saints".',
    ],
    'come-thou-fount' => [
        'soprano' => 'Carries the tune Nettleton, lilting in three, up to its top E-flat on "some", "flaming" and "above".',
        'alto' => 'Sings close under the tune, mostly on E-flat, and climbs with everyone to B-flat on "melodious" and "flaming".',
        'tenor' => 'Sings the words in the middle of the chords, mostly on B-flat, with G and A-flat, up to E-flat on "melodious" and "tongues above".',
        'bass' => 'Sings the roots, mostly E-flat and B-flat, up to A-flat on "heart", "songs", "melodious", "tongues" and "thy".',
    ],
    'nearer-my-god' => [
        'soprano' => 'Carries Mason\'s tune Bethany, calm and even, from the low D on "Nearer" and "That" up to its top E on "all" in "Still all my song" and on the "Nearer" that follows.',
        'alto' => 'Sings the words under the tune, mostly on D, with G, C and B, up to G for "Still all my song shall be, Nearer, my", and down to B on "Nearer", "That" and the last "thee".',
        'tenor' => 'Sings the words in the middle of the chords, mostly on G, between F# and C.',
        'bass' => 'Sings the roots, mostly G, D and C, from the high G on the opening "Nearer" down to the low G on the last "thee".',
    ],
    'greensleeves' => [
        'soprano' => 'Carries the old tune, gentle and lilting, up to its top E on the refrain\'s first and third "Greensleeves", and down to C# on "discourteously" and "delight".',
        'alto' => 'Sings the words beneath the tune, mostly on C# and A, up to F# on "Alas! my" and "I have".',
        'tenor' => 'Sings the words in the middle of the harmony, mostly on F#, G# and A, moving mostly by step.',
        'bass' => 'Sings Macfarren\'s bass line, mostly E, C# and F#, ending on the low F# under the last "Greensleeves".',
    ],
    'jerusalem' => [
        'soprano' => 'Carries Parry\'s broad tune, from the low B on "green?" up to its top E on "Jerusalem".',
        'alto' => 'Sings the words under the tune, mostly on D, B and E, from a low G on "green?" up to A on "Lamb".',
        'tenor' => 'Sings the words in the middle of the harmony, mostly on G and A, from a low D on "England\'s mountains green?" and the "And" after it, up to D on "here".',
        'bass' => 'Follows the lowest notes of Parry\'s accompaniment, mostly G, B and D, down to a low F# in several lines, among them "England\'s", "Lamb of" and "dark Satanic", and up to A on "Countenance Divine".',
    ],
    'lift-every-voice' => [
        'soprano' => 'Carries Rosamond Johnson\'s tune, broad and stately, up to its top E on "rise, High" and "sun, Of", and down to a low B in "full of the faith that the dark past has".',
        'alto' => 'Sings the words under the tune, mostly on B, E and D, and climbs to its top G#, a sixth under the tune, on "rise, High" and "sun, Of".',
        'tenor' => 'Sings the words in the middle of the chords, mostly on G, A and B, up to D on "loud" and "till".',
        'bass' => 'Sings the bass line, mostly G, D and E, and holds a low G through both "Sing a song full of" lines.',
    ],
    'drunken-sailor' => [
        'soprano' => 'Is the shantyman: sings "What shall we do with a drunken sailor" alone, then leads the chorus, up to its top E on "sailor" and "rises".',
        'alto' => 'Rests through the verse and comes in on the chorus, "Hooray and up she rises", mostly on G and F#, ending on a low G on "morning".',
        'tenor' => 'Comes in on the chorus in strong, simple chords, mostly on B and A, up to D on the third "up" and down to E on "morning".',
        'bass' => 'Comes in on the chorus on the roots, mostly E and D, down to a low G on the third "rises".',
    ],
    'leave-her-johnny' => [
        'soprano' => 'Is the shantyman: sings each grumble alone, from "O the times are hard" to "a leaking ship and a harping crew", up to its top D on "times", "bread" and "leaking".',
        'alto' => 'Rests through each grumble and comes in on "Leave her, Johnny, leave her" and "It\'s time for us to leave her", mostly on B, up to D on "leave her" at the end of each "Leave her, Johnny, leave her", and on "leave" in "to leave her".',
        'tenor' => 'Comes in on the answers, mostly on a low E, rising to B at the end of each "Leave her, Johnny, leave her".',
        'bass' => 'Answers on the bass of Sharp\'s chords, mostly a low G and D, rising to the G an octave up at the end of each "Leave her, Johnny, leave her".',
    ],
    'caro-mio-ben' => [
        'soprano' => 'Sings the voice line in Italian, slow and tender, from a low D on the first "languisce" up to its top F on the first "Cessa".',
        'alto' => 'Hums Parisotti\'s harmony on "oo", mostly on E-flat, with D and F, holding through most of the tune\'s short breaths and breathing at its own chord changes.',
        'tenor' => 'Hums the middle of the harmony on "oo", mostly on B-flat, G and A-flat, taking most of its breaths apart from the alto\'s and the bass\'s, sharing only the breaks as the interlude starts, between sections and before the last "languisce il cor".',
        'bass' => 'Hums the bass of Parisotti\'s piano part on "oo", mostly B-flat and E-flat, down to a low F in the middle section.',
    ],
    'shorty-george-blues' => [
        'soprano' => 'Sings Thomas\'s blues tune through all five verses, mostly on G, moving between B-flat, its blue note, and B, from the top D, first on "I wrote", down to D an octave below.',
        'alto' => 'Hums the piano\'s chords on "oo", mostly on D, holding through most of the tune\'s breaths and breathing at its own chord changes.',
        'tenor' => 'Hums the middle of the chords on "oo", mostly on G, with B and A, taking most of its breaths apart from the alto\'s and the bass\'s, all three breathing together between verses and twice near the end.',
        'bass' => 'Sings the roots on "doo", mostly G, with D and C where the chord changes, under every verse.',
    ],
    'o-holy-night' => [
        'soprano' => 'Carries Adam\'s tune, slow and lilting, from a low C on "night" and "birth" up to its top E in "O night divine!".',
        'alto' => 'Sings quiet chords under the verse, mostly on E, and the choir\'s part in the refrain, up to G on "knees!", on the "O" of "O hear", and on "night" and "divine!" in "O night divine!".',
        'tenor' => 'Sings the middle of the chords, mostly on C and G, down to a low E in the verse, first on "night of the" and "birth", and up to D on the last "night".',
        'bass' => 'Sings the organ\'s lowest notes in the verse and the choir\'s bass in the refrain, mostly on C, down to a low G under "night of the dear Saviour\'s", "thrill of hope" and "yonder breaks a".',
    ],
    'deep-river' => [
        'soprano' => 'Rests through the first refrain while the alto has the tune, then floats the refrain above it, mostly on long notes, from a slow "Deep, deep river" to "want to cross over into campground"; in the verse it sings the tune with the alto, in unison, through "gospel feast", then takes the top line. Its highest note, a G, comes on "over" in the second refrain and on "promised" in the verse, its lowest, a D, on the last "river", and it sings G, E-flat or B-flat most of the time.',
        'alto' => 'Carries the tune, twice through the refrain, with its octave leap from "is" up to "over" in "my home is over Jordan", and shares it with the soprano in the verse up to "gospel feast". Its highest note, an E-flat, comes on "over" both times and on "gospel", its lowest, a B-flat, on "into" in the second refrain and on the last "river", and it sings E-flat, G or C most of the time.',
        'tenor' => 'Sings the words in the middle of Burleigh\'s chords, C, B-flat, E-flat or D most of the time, stepping down D, D-flat, C under "Jordan, Deep, deep river" in the first refrain; in the verse it sings "Want to go" while the soprano and alto sing "Oh, don\'t you want to go", then sings "to that gospel feast" with them. Its highest note, a G, comes once, on "all" in "where all is peace?", and its lowest, an F, on the last "river".',
        'bass' => 'Sings Burleigh\'s bass line, on E-flat nearly a third of the time and on E-flat, B-flat, G or A-flat most of it, from its lowest note, an F, on "over" in the first refrain and on "want to cross" in the second, up to its highest, a B-flat, once, on "all" in "where all is peace?". At the close it moves B-flat, B natural, C, B-flat, A-flat, B-flat, E-flat under "is peace? Oh, deep river".',
    ],
    'white-coral-bells' => [
        'soprano' => 'Starts the round alone and sings both verses twice, from its low B-flat on "Lilies" and "That" up to its top D on "our" in "deck our garden walk" and on "the" in "when the fairies sing".',
        'alto' => 'Sings the same tune at the same pitch, coming in four bars after the soprano: nothing new to learn.',
        'tenor' => 'Sings the same tune an octave lower, for lower voices, coming in four bars after the alto.',
        'bass' => 'Sings the same low tune as the tenor, coming in last, four bars after it, and finishing alone on "That could happen only when the fairies sing".',
    ],
    'londons-burning' => [
        'soprano' => 'Starts the round alone and sings it three times through, up to its top C on every "Fire!" and every "pour", and down to the C an octave below on every "London\'s".',
        'alto' => 'Sings the same tune at the same pitch, coming in two bars after the soprano, and stops with everyone on its last "Fire!".',
        'tenor' => 'Sings the same tune an octave lower, for lower voices, coming in two bars after the alto, and stops with everyone on "engines".',
        'bass' => 'Sings the same low tune as the tenor, coming in last, two bars after it, and stops with everyone on "burning".',
    ],
    'three-blind-mice' => [
        'soprano' => 'Starts the round alone and sings it twice through, down to its low C on every "mice" and up to its top C on "all ran", "farmer\'s", "cut off their", "carving", "ever you" and "sight".',
        'alto' => 'Sings the same tune at the same pitch, coming in four bars after the soprano: nothing new to learn.',
        'tenor' => 'Sings the same tune an octave lower, for lower voices, coming in four bars after the alto.',
        'bass' => 'Sings the same low tune as the tenor, coming in last, four bars after it, and finishing alone from "ever you see such a sight" to the last "As three blind mice".',
    ],
    'oh-how-lovely' => [
        'soprano' => 'Starts the round alone and sings it three times through, up to its top C on each "sweetly", and down to its low E-flat on "O", at the end of "lovely" and of each "evening", and for the whole "Ding, dong" line.',
        'alto' => 'Sings the same tune at the same pitch, coming in six bars after the soprano, just as it starts "When the bells are sweetly ringing".',
        'tenor' => 'Sings the same tune an octave lower, for lower voices, coming in six bars after the alto, as the soprano reaches "Ding, dong".',
        'bass' => 'Sings the same low tune as the tenor, coming in last, six bars after it, and finishing alone on the last "Ding, dong, ding, dong, ding, dong!".',
    ],
    'ezekiel-saw-the-wheel' => [
        'soprano' => 'Carries the tune, mostly on G and B, sings each verse\'s solo lines alone, from "Some go to church fo\' to sing an\' shout" to "He\'ll talk \'bout me an\' he\'ll talk \'bout you", starting them on its top E, on "Some", "Befo\'", "Let" and "He\'ll talk", and goes down to its low D on the first syllable of every "Ezekiel", on "An\' de" before "little wheel" and on the first "a" in "\'Tis a wheel in a wheel".',
        'alto' => 'Rests through the soprano\'s solo lines and answers "\'Way in de middle ob de air" with everyone, mostly on B and D, rising to its top E only in the refrain, on "in de" in "\'Way up in de middle", "run by" in "little wheel run by faith" and "by de" in "run by de grace".',
        'tenor' => 'Rests through the soprano\'s solo lines and joins every answer, most often on G, then D, up to its top C on "in de" in "\'Way up in de middle" and down to its low C on "run by" in "little wheel run by faith".',
        'bass' => 'Sings the bass line, mostly on a low G, rests through the soprano\'s solo lines, and rises to its top note, D, on every "\'Way in de middle ob de", on "middle ob de" after "\'Way up in de" and on "grace ob" in "by de grace ob God".',
    ],
    'every-time-i-feel-the-spirit' => [
        'soprano' => 'Carries the tune of the refrain, mostly on E-flat and C, across an octave, from its top E-flat on every "Ev\'ry" and "feel" in "Ev\'ry time I feel the Spirit" down to the E-flat below on every "heart" and "pray.", and rests while the alto sings the verses.',
        'alto' => 'Sings both verses alone, "Upon the mountain my Lord spoke" and "All around me looks so shine", on C, E-flat and G, with an F on "fire" and "all", and in the refrain sings with everyone, mostly on G and A-flat, up to A-flat on "time I feel the" and the start of "moving", and down to C on every "heart".',
        'tenor' => 'Sings the refrain on just two notes, mostly B-flat, rising to E-flat on every "time I feel the" and "moving", and rests while the alto sings the verses.',
        'bass' => 'Sings the refrain mostly on the roots, most often on E-flat, down to its low A-flat on every "time I", and rests while the alto sings the verses.',
    ],
    'were-you-there' => [
        'soprano' => 'Asks each verse\'s question alone, as "Were you there when they crucified my Lord?" in verse 1, holding its last word while the others echo, then sings the rest with everyone, mostly on G and B, up to its top E on "crucified", "nailed", "pierced" and "sun" in each verse\'s second question and on every "Sometimes", and down to its low D on each verse\'s first "Were" and its last "tremble,".',
        'alto' => 'Rests while the soprano asks each question, echoes its end on B, C and B ("were you there?" in verses 1 and 4, "to the tree?" and "in the side?" in verses 2 and 3), then sings with everyone, mostly on B and E, reaching its top B only in each verse\'s second question, on every "Oh!" and on every "Sometimes".',
        'tenor' => 'Echoes the end of each question with the alto and bass, then fills the middle of the chord, most often on G, then C, up to its top C on "me to tremble," and the second "tremble" in "Sometimes it causes me to tremble", and on "crucified", "nailed", "pierced" and "sun" in each verse\'s last line; its low C comes once a verse, in the echo, on "you" or "the".',
        'bass' => 'Echoes the end of each question with the alto and tenor, then sings the bass line, most often on a low G, then C, rising to the G an octave up once a verse, in its last line, on "crucified", on "Him" in "nailed Him" and "pierced Him", and on "refused".',
    ],
    'didnt-my-lord-deliver-daniel' => [
        'soprano' => 'Sings the five-note tune, mostly on C and D, and each verse alone until the others join its last line, up to its top E on "Daniel," after each "Didn\'t my Lord deliver" or "d\'liver" and on "why" in the refrain, and on "belly", "fiery", "forbear", "disappear,", "begin" and "Canaan\'s" in the verses, and down to its low G on the start of each "deliver" or "d\'liver" after "Didn\'t my Lord".',
        'alto' => 'Sings the refrain and each verse\'s last line, mostly on C, a steady low line under the tune, up to its top E on the third "Daniel," of each refrain and on "why not", "Jesus" and "never come" in the verses\' last lines, and down to A on every "every" in the refrain\'s "And why not a every man?".',
        'tenor' => 'Sings the refrain and each verse\'s last line, most often on A, then G, and drops to its low E on "a" and "man?" in each "And why not a every man?", and in the verses on "And why not" and "man?", "King Jesus" and "mine.", and "And I\'ll never come" and "more.".',
        'bass' => 'Sings the roots, mostly on a low A, then C, joins each verse\'s last line on A, with G only on "every", "shall" and "back", and drops to its bottom F on "every" in each refrain\'s "And why not a every man?".',
    ],
    'balm-in-gilead' => [
        'soprano' => 'Carries the tune, mostly on A and C-sharp, and sings both verses alone, "Sometimes I feel discouraged" and "If you cannot preach like Peter", reaching its top E only there, on "discouraged,", "work\'s" and "Spirit" in the first and on "Peter,", "pray" and "Jesus," in the second, and down to its low E on every "To" in "To heal the sin-sick soul".',
        'alto' => 'Rests through both verses and sings Dett\'s alto in the refrain, mostly on C-sharp and E, up to F-sharp, its top note, on every "wounded" and "whole," and on the first "soul." of each refrain.',
        'tenor' => 'Rests through both verses and sings the refrain on just three notes, mostly on A, dropping to E on every "in Gilead,", on "Balm" before each "To make the wounded whole" and on the last "soul." of each refrain, and to G-sharp on every "whole,", the "There is a" after it and "sick" in every "sin-sick".',
        'bass' => 'Sings the roots of Dett\'s chords on just two notes, a low A for three quarters of the time and the E above it on every "whole,", the "There is a" after it and every "sin-sick", and rests through both verses.',
    ],
    'bully-in-the-alley' => [
        'soprano' => 'Is the shantyman: sings the opening refrain\'s two "So help my bob I\'m bully in the alley" lines alone, and in each verse its first line and "Bully in Tinpot alley", most often on G, then B and A, from its low D on every "So" up to its top D on every "I\'m", on "our" in the first lines of verses 1 and 2, on the second "the" in verse 3\'s "She\'s the girl in the alley." and on "in" in every "Bully in Tinpot alley".',
        'alto' => 'Answers "Way ay bully in the alley" with everyone and, in the verses, also sings "So help my bob I\'m bully in the alley", mostly on E, C and D, from a low A on each verse\'s "So" up to its top G on "ay" in both answers of the opening refrain and in each verse\'s last answer.',
        'tenor' => 'Answers with everyone, and in the verses sings "So help my bob I\'m bully in the alley" too, most often on G, up to its top D only once, on "ay" in the opening refrain\'s second "Way ay", and down to a low D on the last "alley." of each verse.',
        'bass' => 'Sings the bass line under the answers, mostly on C and a low G, and in the verses under "So help my bob I\'m bully in the alley" too, rising to its top E only once, on "ay" in the opening refrain\'s first "Way ay".',
    ],
    'haul-on-the-bowline' => [
        'soprano' => 'Is the shantyman: sings the whole chorus alone first, as his call, then each verse\'s first line alone, "Because she had a foretop" and "Because she had a maintop", starting each on its low D on "Because", most often on D, then B, up to its top E on the first "bowline," of the opening call and of the closing chorus.',
        'alto' => 'Rests through the shantyman\'s call and solo lines, joins each verse\'s last line ("Haul on the bowline, the bowline haul", in verse 2 "Haul the bowline") and sings the whole last chorus, mostly on F-sharp and G, up to its top A only there, on "bowline, O" in "Haul on the bowline, O Kitty".',
        'tenor' => 'Rests through the call and the solo lines, then sings each verse\'s last line and the last chorus, mostly on A and D, on its low F-sharp for "Haul on the" at the start of verse 1\'s answer, and up to its top E once, on the last "bowline" before the final "haul".',
        'bass' => 'Rests through the call and the solo lines, then sings the bass line, most often on B, then A and D, down to its low G once, on "darling," in the last chorus, and up to its top F-sharp on "bowline, the" in that chorus\'s last line.',
    ],
    'spanish-ladies' => [
        'soprano' => 'Carries Sharp\'s tune in its old minor form, mostly on A and C, up to its top E on "sail" and "But" in the verse and on "channel" and "From" in each chorus, and down to its low D on "to" in "short time to see you again" and on "is" in each "to Scilly is thirty five leagues".',
        'alto' => 'Sings the words with the tune all through, mostly on C and E, up to its top A only on "strike" in each "Until we strike soundings", and turns the last chord major with a C-sharp on the very last "leagues.".',
        'tenor' => 'Sings the words in the middle of the chord, mostly on E and G, staying on E for most of the opening "Farewell and adieu to you Spanish ladies", and up to its top D on "Until" in each chorus.',
        'bass' => 'Sings the bass line from Sharp\'s left hand, mostly on A and C, up to its top A only once, on "hope" in "But we hope in a short time", and down to its low F on "old" in every "old England", on "like" in "roar like true British sailors" and on "roar" in "we\'ll roar all on the salt seas".',
    ],
    'blow-boys-blow' => [
        'soprano' => 'Is the shantyman: sings both solo lines of every verse alone, among them "A Yankee ship came down the river" and "Why bullock\'s lights and donkey\'s liver.", mostly on B and G, starting each verse on its low D ("A", "And" or "Then") and each second solo line on its top E ("Her", "The", "Why" or "And").',
        'alto' => 'Rests through the solo lines and answers "Blow, boys blow." rising E, G-sharp, A, its top note, and "Blow my bully boys blow." falling G, F-sharp, D to a low B on the last "blow.", the same in every verse.',
        'tenor' => 'Rests through the solo lines and answers in the middle of the chord, mostly on G and A, starting "Blow, boys blow." on its top C in verse 1 and on its low E in every verse after.',
        'bass' => 'Rests through the solo lines and sings the bass of Terry\'s chords, C, E, A under "Blow, boys blow.", with its top E on "boys", then D for "Blow my bully boys" and down to a low G on the last "blow.", the same in every verse.',
    ],
    'maoz-tzur' => [
        'soprano' => 'Carries the traditional tune, most often on E, then B, dipping to its low B on "Maoz" and "Tikon" in verse 1 and on "Yevanim" and "Ufartzu" in verse 5, up to its top E on "matbeach," and "mitzar" in verse 1 and on "kankanim," and "naasa" in verse 5, and sings each verse\'s last line twice.',
        'alto' => 'Sings the words under the tune, mostly a third or a sixth below it, most often on G-sharp, up to its top B only on "mitzar" in verse 1 and "naasa" in verse 5, and crosses a third above the tune, to G-sharp, on the last note of every "hamizbeach." and "urenanim." and on "alai," and "migdalai," in verse 5.',
        'tenor' => 'Sings the middle of the chord, most often on B, then E, up to its top E only on "hamenabeach." in verse 1 and "nes" in verse 5, and down to its low D-sharp on "yeshuati,", "leshabeach.", "tefilati," and "nezabeach." in verse 1 and on "Chashmanim." and "hashemanim." in verse 5.',
        'bass' => 'Sings mostly the roots of the chords, on E just over half the time, then B, up to the higher A only on "hamenabeach." in verse 1 and "naasa" in verse 5, and down to the low A an octave under it on "nae", "toda", "tachin" and every "chanukat hamizbeach." in verse 1, and on "azai", "vetim\'u", "Uminotar" and every "kav\'u shir urenanim." in verse 5.',
    ],
    'oy-chanukah' => [
        'soprano' => 'Carries the Hasidic tune as Lvov printed it, quick and light, most often on C, then A-flat, up to its top F on the second "Khanike," and on "freylekher," each time verse 1 is sung and on "fartribn" and "hamikdesh" in verse 2, and down to its low F on, among others, the first and last words of every verse, "Oy," and "kon." in verse 1 and "Yehude" and "oykh." in verse 2.',
        'alto' => 'Sings Lvov\'s alto part with the words, mostly a third or a sixth below the tune, most often on A-flat, then F, up to its top B-flat on "likhtelekh" each time verse 1 is sung and on "hamakabi" in verse 2, and down to its low A-flat on the last word of every verse, "kon." and "oykh.".',
        'tenor' => 'Sings the words in the middle of the chord, taken from Lvov\'s piano left hand, most often on C, then A-flat, up to its top E on "sheyner," and "azoyner." each time verse 1 is sung and on "rotseyekh," and "lamnatseyekh." in verse 2, and down to its low C on the last word of every verse, "kon." and "oykh.".',
        'bass' => 'Sings the bass line of Lvov\'s piano left hand on "dm", a short note on the beat under the others, once or twice a bar, mostly on F, and joins the words only for the last word of each verse, "kon." and "oykh.", on its low F.',
    ],
    'ein-keloheinu' => [
        'soprano' => 'Carries Freudenthal\'s tune, most often on G, then B, up to its top E on "kemalkenu," in verse 1, "lemalkenu," in verse 3 and "malkenu," in verse 5, and down to its low C-sharp only on "ch\'moshienu." in verse 2 and "moshienu." in verse 4.',
        'alto' => 'Sings under the tune, mostly a third or a sixth below it, most often on D, then G, from its low B on the opening "Ein", "Node" and "Ata hu" of verses 1, 3 and 5 up to its top B on "ein" before "kemalkenu,", "nodeh" before "lemalkenu,", "atah hu" before "malkenu," and the last "moshienu.", where it ends a third above the tune.',
        'tenor' => 'Sings the middle of the chord, most often on A, staying on A for three quarters of verses 2 and 4, and up to its top E on "kemalkenu," in verse 1, "lemalkenu," in verse 3 and the last "atah" in verse 5.',
        'bass' => 'Sings the bass line, on the chords\' roots three quarters of the time, on G and D two thirds of the time, and goes down to its low A only in verses 2 and 4, on "mi chadoneinu," and "ch\'moshienu." and on "baruch adoneinu," and "moshienu.".',
    ],
    'adir-hu' => [
        'soprano' => 'Carries the traditional tune, most often on G, then C, up to its top E on "bimhera," and "veitcha" in every verse, and down to its low E on the names that open each verse ("Adir" and both "adir" in verse 1, "Bachur", "gadol" and "yachid" in verse 2, "Tzadik", "kadosh" and "rachum" in verse 3), and on "beyameinu", the "bekarov." after it and the first "bene," of every verse.',
        'alto' => 'Sings under the tune, a third or a sixth below it most of the time, mostly on E, up to its top A only on "bimhera," and down to its low B only on the "bekarov." after "beyameinu", in every verse.',
        'tenor' => 'Sings the middle of the chord on just five notes, mostly on G, up to C on the third "adir hu," in verse 1, on "yachid hu," and "rachum hu," in verses 2 and 3 and on every second "bimhera," and every "beyameinu", and down to F on the first "bekarov," and the "bekarov." after "beyameinu" in every verse.',
        'bass' => 'Sings mostly the roots of the chords, on a low C most of the time, staying on it under the names that open each verse, up to its top G only on "veito" and down to its low F only on the last "bekarov." of every verse.',
    ],
    'eliyahu-hanavi' => [
        'soprano' => 'Carries Idelsohn\'s folk tune, most often on G, then B-flat and D, down to its low D on "hanavi," and up to its top E-flat only on the last "Eliyahu", before "hagiladi.", the same each time through.',
        'alto' => 'Sings under the tune, mostly a third or a sixth below it, most often on E-flat, then D, down to its low A on "hanavi," and up to its top G on "hatishbi,", the first "Eliyahu," and the "Eliyahu" before "hagiladi.", the same each time through.',
        'tenor' => 'Sings the middle of the chord, most often on B-flat, then G, up to its top D on the first "Eliyahu," each time through, and down to its low D, an octave under it, only on the very last "hagiladi.".',
        'bass' => 'Sings the bass line, most often on G, then B-flat, from its low G on the first "Eliyahu", "hanavi," and "hagiladi." up to its top G, an octave higher, on the "Eliyahu" before "hatishbi,", the same each time through.',
    ],
    'echad-mi-yodea' => [
        'soprano' => 'Carries the traditional tune, most often on F, then C, up to its top D-flat on the first "yodea," and on "shebashamayim" in every verse, and down to its low E only on "uvaaretz.", the last word of every verse.',
        'alto' => 'Sings under the tune, mostly a sixth below it, most often on A-flat, then E-flat, up to its top F on "ani" in verses 1, 3 and 4, on the "shenayim" after "mi yodea," in verse 2 and on every "shebashamayim", and down to its low A-flat on the "Echad", "Shenayim", "Sh\'losha" and "Arba" that open the verses, on the "echad" before every "elokeinu" and on every "uvaaretz.".',
        'tenor' => 'Sings the middle of the chord, most often on A-flat, then F, up to its top B-flat on the first "yodea," in verses 1 and 4 and on every "imahot,", "avot," and "hab\'rit,", and down to its low C on every "uvaaretz.".',
        'bass' => 'Sings the bass line, most often on F, then C, up to its top F on "ani" in verse 2 and on the "yodea," after "ani" in verses 1, 3 and 4, and down to its low F, an octave under it, on the "Echad", "Shenayim", "Sh\'losha" and "Arba" that open the verses, on every "elokeinu" and on every "uvaaretz.".',
    ],
    'ki-lo-naeh' => [
        'soprano' => 'Carries the traditional tune and sings each verse alone, from "Adir bimlucha," to "yomru lo:" and the same lines of verses 2 and 3, most often on A, then F-sharp, up to its top D on every "yae." and on the first "lecha" and the "lecha" before "af" in every answer, and down to its low D on every "Ki" that opens "Ki lo nae,", on every "kahalacha," and on "gedudav", "shinanav" and "temimav".',
        'alto' => 'Rests while the soprano sings each verse alone and joins for "Ki lo nae, ki lo yae." and every answer, mostly a third or a sixth below the tune, most often on D, then C-sharp, up to its top F-sharp on every "yae." and, in every answer, on the first "lecha" and on "ki lecha," and "lecha af lecha,", and down to its low A only on the "Ki lo" that opens every "Ki lo nae,".',
        'tenor' => 'Rests while the soprano sings each verse alone and joins for "Ki lo nae, ki lo yae." and every answer in the middle of the chord, on F-sharp, G and A over nine tenths of the time, most often on F-sharp, up to its top C-sharp on the first "lecha" of every answer and down to its low D on every "nae,".',
        'bass' => 'Rests while the soprano sings each verse alone and joins for "Ki lo nae, ki lo yae." and every answer, singing the bass line, most often on D, then B, up to its top F-sharp on the "lecha" before "Adoshem" in every answer, and down to its low F-sharp, an octave under it, on every "nae," and the "ki" after it, and on "af", the "lecha," after it and "hamamlacha," in every answer.',
    ],
];
